mapper.sql:
FROM mes_pro_process_pool_event_revision report_revision INNER JOIN mes_pro_process_pool_event pool_event ON pool_event.id = report_revision.event_id AND pool_event.tenant_id = report_revision.tenant_id AND pool_event.deleted = 0 AND pool_event.event_type = 'PRODUCTION_SUBMIT' LEFT JOIN mes_pro_work_order work_order ON work_order.id = pool_event.work_order_id AND work_order.tenant_id = pool_event.tenant_id AND work_order.deleted = 0 LEFT JOIN mes_pro_process process ON process.id = pool_event.process_id AND process.tenant_id = pool_event.tenant_id AND process.deleted = 0 LEFT JOIN system_users actual_employee ON actual_employee.id = pool_event.actual_employee_id AND actual_employee.tenant_id = pool_event.tenant_id AND actual_employee.deleted = 0 LEFT JOIN system_users modified_user ON modified_user.id = report_revision.modified_by_user_id AND modified_user.tenant_id = report_revision.tenant_id AND modified_user.deleted = 0 WHERE report_revision.deleted = 0 AND report_revision.revision_status = 'EFFECTIVE' AND pool_event.actual_employee_id IN
#{employeeUserId}
AND work_order.code LIKE CONCAT('%', #{reqVO.workOrderCode}, '%')
AND ( process.code LIKE CONCAT('%', #{reqVO.processKeyword}, '%') OR process.name LIKE CONCAT('%', #{reqVO.processKeyword}, '%') )
AND actual_employee.nickname LIKE CONCAT('%', #{reqVO.actualEmployeeName}, '%')
AND modified_user.nickname LIKE CONCAT('%', #{reqVO.modifiedByName}, '%')
AND report_revision.server_revision_time >= #{reqVO.modifiedAtStart}
AND report_revision.server_revision_time <= #{reqVO.modifiedAtEnd}

mapper.select:
SELECT report_revision.*

ORDER BY report_revision.server_revision_time DESC, report_revision.id DESC
LIMIT #{offset}, #{pageSize}
